"""Catalog E6: managed versions of the as-is parent chain captured from help:effective-pom."""
from __future__ import annotations

import json
from pathlib import Path

import pytest

from sbmig.build import effective as effmod
from sbmig.build.effective import capture_effective_depmgmt, effective_version, load_effective, parse_effective_pom
from sbmig.build.mvn import ProcessResult
from sbmig.core.workspace import Workspace

REPO_ROOT = Path(__file__).resolve().parents[2]

SINGLE = """<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by Maven Help Plugin -->
<project xmlns="http://maven.apache.org/POM/4.0.0">
  <modelVersion>4.0.0</modelVersion>
  <parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId>
    <version>2.7.18</version></parent>
  <groupId>com.example</groupId><artifactId>demo</artifactId><version>1.0</version>
  <properties><java.version>1.8</java.version><lombok.version>1.18.30</lombok.version></properties>
  <dependencyManagement><dependencies>
    <dependency><groupId>org.projectlombok</groupId><artifactId>lombok</artifactId><version>1.18.30</version></dependency>
    <dependency><groupId>com.h2database</groupId><artifactId>h2</artifactId><version>2.1.214</version></dependency>
  </dependencies></dependencyManagement>
  <dependencies>
    <dependency><groupId>org.projectlombok</groupId><artifactId>lombok</artifactId><version>1.18.30</version></dependency>
    <dependency><groupId>com.acme</groupId><artifactId>x</artifactId><version>${unresolved}</version></dependency>
  </dependencies>
  <build><pluginManagement><plugins>
    <plugin><artifactId>maven-compiler-plugin</artifactId><version>3.10.1</version></plugin>
  </plugins></pluginManagement></build>
</project>
"""

MULTI = """<?xml version="1.0" encoding="UTF-8"?>
<!-- comment -->
<projects>
  <!-- module a -->
  <project xmlns="http://maven.apache.org/POM/4.0.0">
    <parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId>
      <version>2.7.18</version></parent>
    <groupId>shop</groupId><artifactId>order</artifactId>
    <dependencyManagement><dependencies>
      <dependency><groupId>g</groupId><artifactId>a</artifactId><version>1.0</version></dependency>
    </dependencies></dependencyManagement>
  </project>
  <project xmlns="http://maven.apache.org/POM/4.0.0">
    <parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId>
      <version>3.3.13</version></parent>
    <groupId>shop</groupId><artifactId>user</artifactId>
    <dependencyManagement><dependencies>
      <dependency><groupId>g</groupId><artifactId>a</artifactId><version>2.0</version></dependency>
      <dependency><groupId>g</groupId><artifactId>b</artifactId><version>3.0</version></dependency>
    </dependencies></dependencyManagement>
    <properties><x>2</x></properties>
  </project>
</projects>
"""


def test_parse_single_and_multi():
    d = parse_effective_pom(SINGLE)
    assert d["managed"] == {"org.projectlombok:lombok": "1.18.30", "com.h2database:h2": "2.1.214"}
    assert d["direct"] == {"org.projectlombok:lombok": "1.18.30"}               # ${unresolved} skipped
    assert d["plugins"]["org.apache.maven.plugins:maven-compiler-plugin"] == "3.10.1"
    assert d["properties"]["java.version"] == "1.8"
    assert d["parent"] == "org.springframework.boot:spring-boot-starter-parent:2.7.18"
    assert d["modules"] == ["com.example:demo"]
    m = parse_effective_pom(MULTI.encode())
    assert m["managed"] == {"g:a": "1.0", "g:b": "3.0"}                          # first wins
    assert m["parent"].endswith(":2.7.18") and m["modules"] == ["shop:order", "shop:user"]
    assert m["by_module"]["shop:user"]["managed"]["g:a"] == "2.0"
    assert m["by_module"]["shop:user"]["parent"].endswith(":3.3.13")
    assert parse_effective_pom("garbage")["managed"] == {}


@pytest.fixture()
def ws(tmp_path: Path) -> Workspace:
    root = tmp_path / "project"
    root.mkdir()
    (root / "pom.xml").write_text("<project/>", encoding="utf-8")
    return Workspace(root, tmp_path / "run", "t")


def test_capture_writes_json_and_merges(ws: Workspace, cfg, monkeypatch):
    docs = iter([SINGLE, MULTI])
    cmds: list[list[str]] = []

    def fake_run(cmd, *, cwd, env, log_path, timeout_s):
        cmds.append(list(cmd))
        out = next(c.split("=", 1)[1] for c in cmd if c.startswith("-Doutput="))
        Path(out).write_text(next(docs), encoding="utf-8")
        return ProcessResult(exit_code=0, text="", duration_s=0.1)
    monkeypatch.setattr(effmod, "run_logged", fake_run)
    p = capture_effective_depmgmt(ws, cfg)
    assert p == ws.run_dir / "effective" / "depmgmt.json" and p.is_file()
    assert any(c.endswith(":effective-pom") for c in cmds[0]) and "-pl" not in cmds[0]
    assert json.loads(p.read_text())["managed"]["org.projectlombok:lombok"] == "1.18.30"
    capture_effective_depmgmt(ws, cfg, module="svc")
    assert cmds[1][cmds[1].index("-pl") + 1] == "svc"
    d = load_effective(ws)
    assert d["managed"]["org.projectlombok:lombok"] == "1.18.30" and d["managed"]["g:b"] == "3.0"
    assert d["parent"].endswith(":2.7.18")                                      # first capture wins
    assert effective_version(ws, "g:a") == "1.0"
    assert effective_version(ws, "g:a", module="user") == "2.0"                 # module's own parent chain
    assert effective_version(ws, "org.projectlombok:lombok", module="nope") == "1.18.30"
    assert effective_version(ws, "x:y") is None


def test_capture_failure_returns_none(ws: Workspace, cfg, monkeypatch):
    monkeypatch.setattr(effmod, "run_logged", lambda cmd, **k: ProcessResult(
        exit_code=1, text="[ERROR] Non-resolvable parent POM for com.x:y:1: Could not find artifact", duration_s=0.1))
    assert capture_effective_depmgmt(ws, cfg) is None
    assert load_effective(ws) == {"managed": {}, "direct": {}, "plugins": {}, "properties": {}, "parent": None,
                                  "modules": [], "by_module": {}}
    journal = (ws.run_dir / "journal.jsonl").read_text()
    assert "Non-resolvable parent POM" in journal

    def boom(*a, **k):
        raise OSError("disk full")
    monkeypatch.setattr(effmod, "run_logged", boom)
    assert capture_effective_depmgmt(ws, cfg) is None
    (ws.run_dir / "effective").mkdir(exist_ok=True)
    (ws.run_dir / "effective" / "depmgmt.json").write_text("{not json", encoding="utf-8")
    assert load_effective(ws)["managed"] == {}


@pytest.mark.integration
def test_real_effective_pom_boot2(tmp_path: Path, cfg):
    jdk21 = "/Users/acandiatale/Library/Java/JavaVirtualMachines/corretto-21.0.1/Contents/Home"
    if not Path(jdk21).is_dir():
        pytest.skip("JDK 21 not available")
    cfg.build.java_home = jdk21
    w = Workspace.from_input(REPO_ROOT / "fixtures/projects/boot2", tmp_path / "out", run_id="eff")
    assert capture_effective_depmgmt(w, cfg) is not None
    d = load_effective(w)
    assert d["parent"].startswith("org.springframework.boot:spring-boot-starter-parent:")
    assert d["managed"].get("org.projectlombok:lombok")
